def verify_contract(path: Path, tokens: tuple[str, ...], label: str) -> None:
    if not path.exists():
        raise RuntimeError(f"{label} production module missing: {path}")
    text = path.read_text(encoding="utf-8")
    missing = [token for token in tokens if token not in text]
    if missing:
        raise RuntimeError(f"{label} production contract mismatch: {missing}")


def write_full(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.strip() + "\n", encoding="utf-8")
    print(f"[OK] FULL REPLACEMENT: {path}")


